import numpy as np
class BendMemory:
 def __init__(self,model,asset):
  self.model=model;self.edges=model.edge_indices.numpy();self.rest=model.edge_rest_angle.numpy().copy();self.memory=self.rest.astype(float);self.dwell=np.zeros(len(self.rest));self.sign=np.zeros(len(self.rest));self.steps=0;self.max_energy_proxy_increase=0.;self.max_step_change=0.
  assert len(self.edges)==len(self.rest);self.valid=(self.edges[:,:2]>=0).all(1);self.idx=np.maximum(self.edges,0);p=asset['source_positions'];length=np.linalg.norm(p[self.idx[:,3]]-p[self.idx[:,2]],axis=1);self.eligible=self.valid&(abs(self.rest)<1e-6)&(length>=.005);self.cap=np.deg2rad(5);self.yield_angle=np.deg2rad(10)
 def update(self,q,dt):
  x0,x1,x2,x3=[q[self.idx[:,i]].astype(float) for i in range(4)];v1=x2-x0;v2=x3-x0;v3=x3-x1;v4=x2-x1;e=x3-x2;n1=np.cross(v1,v2);n2=np.cross(v3,v4);l1=np.linalg.norm(n1,axis=1);l2=np.linalg.norm(n2,axis=1);le=np.linalg.norm(e,axis=1);good=self.valid&(le>1e-12)&(l1>1e-6*np.linalg.norm(v1,axis=1)*np.linalg.norm(v2,axis=1))&(l2>1e-6*np.linalg.norm(v3,axis=1)*np.linalg.norm(v4,axis=1));u=n1/np.maximum(l1[:,None],1e-30);v=n2/np.maximum(l2[:,None],1e-30);w=e/np.maximum(le[:,None],1e-30);theta=np.arctan2(np.einsum('ij,ij->i',np.cross(u,v),w),np.einsum('ij,ij->i',u,v));elastic=theta-self.memory;sign=np.sign(elastic);over=self.eligible&good&(abs(elastic)>self.yield_angle);same=sign==self.sign;old=self.dwell.copy();self.dwell=np.where(over,np.where(same,old+dt,dt),0);self.sign=np.where(over,sign,0);active_dt=np.clip(np.maximum(self.dwell-.1,0)-np.maximum(np.where(same,old,0)-.1,0),0,dt);excess=sign*np.maximum(abs(elastic)-self.yield_angle,0);delta=np.clip((1-np.exp(-active_dt/.5))*excess,-.1*active_dt,.1*active_dt);delta[~over]=0;candidate=np.clip(self.memory+delta,self.rest-self.cap,self.rest+self.cap);candidate=candidate.astype(np.float32).astype(float);diff=(theta-candidate)**2-(theta-self.memory)**2;self.max_energy_proxy_increase=max(self.max_energy_proxy_increase,float(diff.max()));assert diff.max()<1e-7;assert np.array_equal(candidate[~self.eligible],self.rest[~self.eligible]);assert abs(candidate-self.rest).max()<=self.cap+1e-7;self.max_step_change=max(self.max_step_change,float(abs(candidate-self.memory).max()));assert self.max_step_change<=.1*dt+1e-7;self.memory=candidate;self.model.edge_rest_angle.assign(candidate.astype(np.float32));self.steps+=1
 def save(self,path):
  np.savez_compressed(path,rest=self.rest,memory=self.memory,dwell=self.dwell,sign=self.sign,eligible=self.eligible,edges=self.edges)
 def report(self):
  return dict(steps=self.steps,eligible=int(self.eligible.sum()),changed=int((abs(self.memory-self.rest)>1e-8).sum()),max_offset_rad=float(abs(self.memory-self.rest).max()),max_step_change_rad=self.max_step_change,max_local_energy_proxy_increase=self.max_energy_proxy_increase,parameters={'yield_deg':10,'cap_deg':5,'rate_rad_s':.1,'tau_s':.5,'same_sign_dwell_s':.1},limitations='Uncalibrated bounded rest-curvature approximation on initially flat sourceedges>=5mm; authored folds preserved. Updated after completed1/240s step; no position/velocity edits. CPU readbacks add overhead. Local fixedq energyproxy only, not fullenergy certification.')
